"use client";

import { useState, useEffect } from "react";
import { X, Trash2, Phone, Star, Edit2, Check, Loader2, MapPin } from "lucide-react";

export default function AddressPage() {
  const [addresses, setAddresses] = useState<any[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingAddress, setEditingAddress] = useState<any>(null);

  return (
    <div className="min-h-screen bg-background text-foreground pb-20">
      <main className="max-w-6xl mx-auto px-4 py-12">
        <div className="flex justify-between items-end mb-10">
          <div>
            <h1 className="text-3xl font-black uppercase tracking-tighter">My Addresses</h1>
            <p className="text-foreground-muted">Fast checkout starting with your pincode.</p>
          </div>
          <button
            onClick={() => { setEditingAddress(null); setIsModalOpen(true); }}
            className="bg-brand text-brand-foreground px-8 py-3.5 rounded-4xl font-bold shadow-lg flex items-center gap-2 hover:opacity-90 transition-all active:scale-95"
          >
            <Plus size={20} /> Add New
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {addresses.map((addr) => (
            <AddressCard 
              key={addr.id} 
              address={addr} 
              onEdit={(a: any) => { setEditingAddress(a); setIsModalOpen(true); }} 
              onDelete={(id: string) => setAddresses(addresses.filter(a => a.id !== id))}
            />
          ))}
        </div>
      </main>

      {isModalOpen && (
        <AddressFormModal 
          initialData={editingAddress} 
          onClose={() => setIsModalOpen(false)} 
          onSave={(data: any) => {
            const updated = editingAddress 
              ? addresses.map(a => a.id === editingAddress.id ? data : a)
              : [...addresses, { ...data, id: Date.now().toString() }];
            setAddresses(updated);
            setIsModalOpen(false);
          }} 
        />
      )}
    </div>
  );
}

const AddressFormModal = ({ initialData, onClose, onSave }: any) => {
  const [formData, setFormData] = useState<any>(initialData || { type: "Home" });
  const [loading, setLoading] = useState(false);

  // STEP 1: Pincode Auto-fill Logic
  useEffect(() => {
    if (formData.pincode?.length === 6) {
      const fetchDetails = async () => {
        setLoading(true);
        try {
          const res = await fetch(`https://api.postalpincode.in/pincode/${formData.pincode}`);
          const data = await res.json();
          if (data[0].Status === "Success") {
            const details = data[0].PostOffice[0];
            setFormData((prev: any) => ({
              ...prev,
              state: details.State,
              district: details.District,
              // We leave city empty or set a hint, user fills manually
            }));
          }
        } catch (e) { console.error("API Error"); }
        finally { setLoading(false); }
      };
      fetchDetails();
    }
  }, [formData.pincode]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-background/60 backdrop-blur-md" onClick={onClose} />
      <div className="relative bg-background-elevated w-full max-w-xl rounded-4xl shadow-2xl flex flex-col max-h-[90vh] overflow-hidden border border-border">
        
        <div className="px-8 py-6 border-b border-border flex justify-between items-center">
          <h2 className="text-xl font-black uppercase tracking-tighter">Delivery Address</h2>
          <button onClick={onClose} className="p-2 hover:bg-background-muted rounded-full"><X size={24} /></button>
        </div>

        <div className="p-8 overflow-y-auto no-scrollbar space-y-8">
          {/* PRIORITY 1: PINCODE & LOCATION (The Lock-in) */}
          <div className="grid grid-cols-2 gap-4">
            <div className="relative">
              <Input label="Pincode" placeholder="6 Digits" value={formData.pincode || ""} onChange={(v) => setFormData({...formData, pincode: v.slice(0,6)})} />
              {loading && <Loader2 className="absolute right-3 bottom-3 animate-spin text-brand" size={16} />}
            </div>
            <div className="bg-background-muted rounded-2xl p-3 border border-border flex flex-col justify-center">
              <span className="text-[9px] font-black uppercase text-foreground-subtle tracking-widest">Region</span>
              <p className="text-xs font-bold truncate">{formData.district ? `${formData.district}, ${formData.state}` : "Auto-filled"}</p>
            </div>
          </div>

          {/* PRIORITY 2: MANUAL FIELDS */}
          <div className="space-y-4">
            <Input label="City / Town" placeholder="e.g. Puthanathani" value={formData.city || ""} onChange={(v) => setFormData({...formData, city: v})} />
            <Input label="House No. / Building" placeholder="Flat, Floor, House Name" value={formData.addressLine1 || ""} onChange={(v) => setFormData({...formData, addressLine1: v})} />
            <Input label="Area / Landmark (Optional)" placeholder="Street or famous place nearby" value={formData.addressLine2 || ""} onChange={(v) => setFormData({...formData, addressLine2: v})} />
          </div>

          <hr className="border-border border-dashed" />

          {/* PRIORITY 3: CONTACT INFO (Final Step) */}
          <div className="space-y-4">
            <Input label="Recipient Name" placeholder="Who is receiving the order?" value={formData.name || ""} onChange={(v) => setFormData({...formData, name: v})} />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <Input label="Phone Number" prefix="+91" value={formData.phone || ""} onChange={(v) => setFormData({...formData, phone: v})} />
              <Input label="Alt Phone (Optional)" prefix="+91" value={formData.altPhone || ""} onChange={(v) => setFormData({...formData, altPhone: v})} />
            </div>
          </div>

          {/* FINAL SETTINGS */}
          <div className="flex items-center justify-between pt-2">
            <div className="flex gap-2">
              {["Home", "Work"].map(t => (
                <button key={t} type="button" onClick={() => setFormData({...formData, type: t})}
                  className={`px-6 py-2 rounded-full text-[10px] font-black border transition-all uppercase tracking-widest ${formData.type === t ? "bg-brand text-brand-foreground border-brand" : "bg-background text-foreground-muted border-border"}`}>
                  {t}
                </button>
              ))}
            </div>
            <label className="flex items-center gap-2 cursor-pointer group">
              <div className={`w-5 h-5 rounded border-2 flex items-center justify-center transition-all ${formData.isDefault ? "bg-brand border-brand" : "border-border"}`}>
                {formData.isDefault && <Check size={12} className="text-brand-foreground" />}
              </div>
              <input type="checkbox" className="hidden" checked={formData.isDefault} onChange={(e) => setFormData({...formData, isDefault: e.target.checked})} />
              <span className="text-[10px] font-bold text-foreground-muted group-hover:text-foreground uppercase tracking-widest">Set Default</span>
            </label>
          </div>
        </div>

        <div className="px-8 py-5 border-t border-border bg-background-muted flex gap-4">
          <button type="button" form="address-form" onClick={(e) => { e.preventDefault(); onSave(formData); }} className="flex-1 px-6 py-3.5 rounded-4xl bg-brand text-brand-foreground font-black shadow-lg uppercase text-xs tracking-widest">
            Confirm Address
          </button>
        </div>
      </div>
    </div>
  );
};

// Reusable Small Input
const Input = ({ label, value, onChange, prefix, placeholder }: any) => (
  <div className="space-y-1 w-full">
    <label className="text-[9px] font-black uppercase tracking-widest text-foreground-subtle ml-1">{label}</label>
    <div className="relative">
      {prefix && <span className="absolute left-3 top-1/2 -translate-y-1/2 text-foreground-subtle text-xs font-bold">{prefix}</span>}
      <input 
        className={`w-full bg-background border border-border rounded-xl py-2.5 text-xs font-bold outline-none focus:border-brand transition-all ${prefix ? "pl-10" : "px-3"}`}
        value={value} placeholder={placeholder} onChange={(e) => onChange(e.target.value)} 
      />
    </div>
  </div>
);